def transform(grid):
    out=[row[:] for row in grid]
    # Identify enclosed regions of the dominant background, framed by the other color.
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    frame=next((v for row in grid for v in row if v!=bg),bg)
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=bg or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]; boundary=set(); edge=False
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if not (0<=yy<h and 0<=xx<w): edge=True; continue
            if grid[yy][xx]==bg and (yy,xx) not in seen:
              seen.add((yy,xx)); stack.append((yy,xx))
            elif grid[yy][xx]!=0: boundary.add(grid[yy][xx])
        if not edge and frame in boundary:
          for y,x in comp: out[y][x]=4
    return out

